package com.lexorion.payroll.service;
import com.lexorion.payroll.api.PayRunDtos.PayRunResponse;import com.lexorion.payroll.entitlement.PayrollProcessingEntitlementGate;import org.springframework.stereotype.Service;
@Service public class PayRunProcessingService{private final PayrollWorkspaceScope scope;private final PayrollProcessingEntitlementGate entitlement;private final PayRunTransactions transactions;private final PayRunService runs;private final io.micrometer.core.instrument.MeterRegistry metrics;public PayRunProcessingService(PayrollWorkspaceScope s,PayrollProcessingEntitlementGate e,PayRunTransactions t,PayRunService r,io.micrometer.core.instrument.MeterRegistry metrics){scope=s;entitlement=e;transactions=t;runs=r;this.metrics=metrics;}public PayRunResponse process(String key){entitlement.requireProcessing(scope.context());transactions.begin(key);try{transactions.complete(key);return runs.get(key);}catch(RuntimeException failure){metrics.counter("lexorion.payroll.processing.failures").increment();transactions.fail(key);throw failure;}}}
